alter table public.delivery_assignments add column if not exists checked_in_at timestamptz, add column if not exists check_in_lat numeric, add column if not exists check_in_lng numeric, add column if not exists check_out_at timestamptz, add column if not exists check_out_lat numeric, add column if not exists check_out_lng numeric, add column if not exists route_started_at timestamptz, add column if not exists last_driver_lat numeric, add column if not exists last_driver_lng numeric, add column if not exists last_driver_location_at timestamptz, add column if not exists route_note text; create index if not exists delivery_assignments_driver_live_idx on public.delivery_assignments (assigned_staff_id, status, last_driver_location_at desc) where status in ('assigned','picked_up','out_for_delivery');;
